import { instantiate, Node, Prefab, Tween, MeshRenderer, Material } from 'cc';
import { ModelKey, PlatformSpec } from '../core/types';
import { PlatformView } from './PlatformView';
interface Slot {
    node: Node; view: PlatformView; id: number | null; model: ModelKey | null;
    materials: { renderer: MeshRenderer; shared: (Material | null)[] }[];
}

/** Bounded wrapper pool. Only view instances own state; imported assets stay read-only. */
export class PlatformPool {
    private readonly slots: Slot[] = [];
    constructor(private readonly parent: Node, private readonly rect: Prefab, private readonly rect01: Prefab,
        private readonly circle: Prefab, private readonly models: readonly Prefab[], private readonly keys: readonly ModelKey[], private readonly limit: number) {
        if (models.length !== keys.length) throw new Error('10 explicit model Prefabs required');
    }
    sync(specs: readonly PlatformSpec[]): void {
        if (specs.length > this.limit) throw new Error('platform pool limit exceeded');
        const wanted = new Set(specs.map(s => s.id));
        for (const slot of this.slots) if (slot.id !== null && !wanted.has(slot.id)) this.recycle(slot);
        for (const spec of specs) {
            let slot = this.slots.find(s => s.id === spec.id);
            if (!slot) {
                slot = this.slots.find(s => s.id === null);
                if (!slot) {
                    if (this.slots.length >= this.limit) throw new Error('no free platform slot');
                    const prefab = spec.modelKey === 'block_03' ? this.circle : spec.modelKey === 'block_01' ? this.rect01 : this.rect;
                    const node = instantiate(prefab); this.parent.addChild(node);
                    const view = node.getComponent(PlatformView);
                    if (!view || !view.visual) throw new Error('stage01 PlatformView/Visual missing');
                    slot = { node, view, id: null, model: null, materials: [] }; this.slots.push(slot);
                }
                if (slot.model !== spec.modelKey) this.setModel(slot, spec.modelKey);
                slot.id = spec.id; slot.node.name = `Platform_${spec.id}_${spec.modelKey}`; slot.node.active = true;
            }
            slot.view.apply(spec);
        }
    }
    get count(): number { return this.slots.length; }
    clear(): void { this.slots.forEach(slot => this.recycle(slot)); }
    destroy(): void { this.slots.forEach(slot => slot.node.destroy()); this.slots.length = 0; }
    private setModel(slot: Slot, model: ModelKey): void {
        const visual = slot.view.visual!;
        for (const child of [...visual.children]) { child.removeFromParent(); child.destroy(); }
        const prefab = this.models[this.keys.indexOf(model)];
        if (!prefab) throw new Error(`missing model ${model}`);
        visual.addChild(instantiate(prefab)); slot.model = model;
        slot.materials = slot.node.getComponentsInChildren(MeshRenderer).map(renderer => ({ renderer, shared: [...renderer.sharedMaterials] }));
    }
    private recycle(slot: Slot): void {
        const stop = (node: Node): void => { Tween.stopAllByTarget(node); node.children.forEach(stop); };
        stop(slot.node);
        for (const entry of slot.materials) entry.shared.forEach((material, index) => entry.renderer.setSharedMaterial(material, index));
        slot.view.resetForPool(); slot.id = null; slot.node.active = false;
    }
}

import { _decorator, Component, Node } from 'cc';
import { DEFAULT_GAME_CONFIG } from '../core/config';
import { PlatformSpec } from '../core/types';

const { ccclass, property } = _decorator;

/** Root = top center; collision metadata deliberately excludes the shadow. */
@ccclass('PlatformView')
export class PlatformView extends Component {
    @property(Node) visual: Node | null = null;
    @property modelKey = 'block_00';
    @property shape = 'rect';
    @property halfX = DEFAULT_GAME_CONFIG.platformWidth / 2;
    @property halfZ = DEFAULT_GAME_CONFIG.platformDepth / 2;
    @property radius = DEFAULT_GAME_CONFIG.platformWidth / 2;
    @property height = DEFAULT_GAME_CONFIG.platformHeight;
    @property horizontalScale = 1;

    spec: PlatformSpec | null = null;

    apply(spec: PlatformSpec): void {
        this.spec = spec; this.modelKey = spec.modelKey; this.shape = spec.shape;
        this.node.setPosition(spec.centerXZ.x, spec.topY, spec.centerXZ.z);
        this.halfX = spec.shape === 'rect' ? spec.halfExtent.x : spec.radius;
        this.halfZ = spec.shape === 'rect' ? spec.halfExtent.z : spec.radius;
        this.radius = spec.shape === 'circle' ? spec.radius : 0;
        this.setHorizontalScale(spec.horizontalScale);
    }
    resetForPool(): void {
        this.unscheduleAllCallbacks(); this.spec = null; this.modelKey = ''; this.shape = '';
        this.halfX = 0; this.halfZ = 0; this.radius = 0; this.horizontalScale = 1;
        this.node.setPosition(0, 0, 0); this.node.setRotationFromEuler(0, 0, 0); this.node.setScale(1, 1, 1);
        this.visual?.setRotationFromEuler(0, 0, 0);
        this.visual?.setScale(1, 1, 1); this.visual?.setPosition(0, -this.height / 2, 0);
    }

    setHorizontalScale(scale: number): void {
        if (!Number.isFinite(scale) || scale < DEFAULT_GAME_CONFIG.minPlatformScale || scale > DEFAULT_GAME_CONFIG.maxPlatformScale) {
            throw new RangeError('horizontalScale must be in [0.8, 1]');
        }
        this.horizontalScale = scale;
        this.visual?.setScale(scale, 1, scale);
    }
}

import { input, Input, EventKeyboard, EventMouse, EventTouch, KeyCode, game, Game, Node, UITransform, Button, EditBox, BlockInputEvents, Vec2 } from 'cc';

export interface InputSink {
    press(source: string): boolean;
    release(source: string): void;
    cancel(source?: string, reason?: string): void;
    pause(reason: string): void;
    command(key: KeyCode): void;
    blocked(): boolean;
}

/** The physical-down set is independent of gameplay owner; rejected busy inputs never become buffered presses. */
export class InputAdapter {
    private readonly down = new Set<string>();
    private owner: string | null = null;
    private bound = false;
    constructor(private readonly sink: InputSink, private readonly ui: Node) {}
    bind(): void {
        if (this.bound) return;
        this.bound = true;
        input.on(Input.EventType.KEY_DOWN, this.keyDown, this);
        input.on(Input.EventType.KEY_UP, this.keyUp, this);
        input.on(Input.EventType.MOUSE_DOWN, this.mouseDown, this);
        input.on(Input.EventType.MOUSE_UP, this.mouseUp, this);
        input.on(Input.EventType.TOUCH_START, this.touchDown, this);
        input.on(Input.EventType.TOUCH_END, this.touchUp, this);
        input.on(Input.EventType.TOUCH_CANCEL, this.touchCancel, this);
        game.on(Game.EVENT_HIDE, this.hide, this);
        if (typeof window !== 'undefined') window.addEventListener('blur', this.blur);
        if (typeof document !== 'undefined') document.addEventListener('visibilitychange', this.visibility);
    }
    unbind(): void {
        if (!this.bound) return;
        this.bound = false;
        input.off(Input.EventType.KEY_DOWN, this.keyDown, this);
        input.off(Input.EventType.KEY_UP, this.keyUp, this);
        input.off(Input.EventType.MOUSE_DOWN, this.mouseDown, this);
        input.off(Input.EventType.MOUSE_UP, this.mouseUp, this);
        input.off(Input.EventType.TOUCH_START, this.touchDown, this);
        input.off(Input.EventType.TOUCH_END, this.touchUp, this);
        input.off(Input.EventType.TOUCH_CANCEL, this.touchCancel, this);
        game.off(Game.EVENT_HIDE, this.hide, this);
        if (typeof window !== 'undefined') window.removeEventListener('blur', this.blur);
        if (typeof document !== 'undefined') document.removeEventListener('visibilitychange', this.visibility);
        this.reset(); this.down.clear();
    }
    reset(): void { this.sink.cancel(this.owner || undefined, 'input-reset'); this.owner = null; }
    private begin(source: string, blocked: boolean): void {
        if (this.down.has(source)) return;
        this.down.add(source);
        if (!blocked && !this.sink.blocked() && this.owner === null && this.sink.press(source)) this.owner = source;
    }
    private end(source: string, cancel = false): void {
        this.down.delete(source);
        if (this.owner !== source) return;
        this.owner = null;
        if (cancel) this.sink.cancel(source, 'touch-cancel'); else this.sink.release(source);
    }
    private keyDown(event: EventKeyboard): void {
        if (event.keyCode === KeyCode.SPACE) this.begin('space', this.formFocused());
        else {
            const source = `key:${event.keyCode}`;
            if (!this.down.has(source) && !this.formFocused()) { this.down.add(source); this.sink.command(event.keyCode); }
        }
    }
    private keyUp(event: EventKeyboard): void {
        if (event.keyCode === KeyCode.SPACE) this.end('space'); else this.down.delete(`key:${event.keyCode}`);
    }
    private mouseDown(event: EventMouse): void { if (event.getButton() === 0) this.begin('mouse-left', this.hitUI(event.getLocation())); }
    private mouseUp(event: EventMouse): void { if (event.getButton() === 0) this.end('mouse-left'); }
    private touchDown(event: EventTouch): void { this.begin(`touch:${event.getID()}`, this.hitUI(event.getLocation())); }
    private touchUp(event: EventTouch): void { this.end(`touch:${event.getID()}`); }
    private touchCancel(event: EventTouch): void { this.end(`touch:${event.getID()}`, true); }
    private hitUI(point: Vec2): boolean {
        const nodes = this.ui.getComponentsInChildren(UITransform);
        return nodes.some(ui => ui.node.activeInHierarchy && (
            ui.getComponent(Button)?.enabled || ui.getComponent(EditBox)?.enabled || ui.getComponent(BlockInputEvents)?.enabled
        ) && ui.hitTest(point));
    }
    private formFocused(): boolean {
        if (typeof document === 'undefined') return false;
        const element = document.activeElement as HTMLElement | null;
        return !!element && (element.tagName === 'INPUT' || element.tagName === 'TEXTAREA' || element.isContentEditable);
    }
    private hide(): void { this.reset(); this.sink.pause('background'); }
    private readonly blur = (): void => { this.reset(); this.sink.pause('blur'); };
    private readonly visibility = (): void => { if (document.hidden) this.hide(); };
}

import { createGameConfig, DEFAULT_GAME_CONFIG, normalizeSeed } from './config';
import { assertReachable, classifyLanding, directionToTarget } from './geometry';
import { chargeDistance, descendingLandingTime, sampleJump } from './motion';
import { PlatformGenerator } from './platforms';
import { RunCommand, RunStateMachine } from './state-machine';
import { DomainEvent, FootPosition, GameConfig, PlatformSpec, ReplayResult, RunState } from './types';

/** Synchronous one-tick owner of rules; no view callbacks can drive its timers. */
export class JumpGameplay {
    private readonly config: Readonly<GameConfig>;
    private readonly machine: RunStateMachine;
    private generator: PlatformGenerator | null = null;
    private pool: readonly PlatformSpec[] = Object.freeze([]);
    private position: FootPosition = Object.freeze({ x: 0, y: 0, z: 0 });
    private queue: DomainEvent[] = [];
    private replayResults: readonly ReplayResult[] = Object.freeze([]);
    private phaseStartTick = 0;
    private nextPreview: PlatformSpec | null = null;
    constructor(config: GameConfig = DEFAULT_GAME_CONFIG) {
        this.config = createGameConfig(config); this.machine = new RunStateMachine(this.config);
    }
    get state(): Readonly<RunState> { return this.machine.state; }
    get foot(): FootPosition { return this.position; }
    get platforms(): readonly PlatformSpec[] { return this.pool; }
    get current(): PlatformSpec | undefined { return this.pool.find(p => p.id === this.state.currentId); }
    get target(): PlatformSpec | undefined { return this.pool.find(p => p.id === this.state.targetId); }
    get holdSeconds(): number {
        return this.state.phase === 'charging' ? Math.min(this.config.maxChargeSeconds,
            (this.state.tick - this.state.chargeStartTick!) * this.config.fixedStepSeconds) : 0;
    }
    get results(): readonly ReplayResult[] { return this.replayResults; }
    drainEvents(): DomainEvent[] { const events = this.queue; this.queue = []; return events; }
    start(seed: number = this.config.seed): boolean {
        // Prepare first: an invalid seed/config must not invalidate the existing run.
        try { seed = normalizeSeed(seed); } catch (_) { return false; }
        const generator = new PlatformGenerator(seed, this.config), initial = generator.initial();
        const preview = generator.next(initial[1]).platform;
        const result = this.machine.dispatch({ type: 'start', seed });
        if (!result.accepted) return false;
        this.generator = generator; this.pool = Object.freeze([...initial, preview]);
        this.position = Object.freeze({ ...initial[0].centerXZ, y: initial[0].topY });
        this.queue = [...result.events]; this.replayResults = Object.freeze([]);
        this.phaseStartTick = 0; this.nextPreview = null;
        return true;
    }
    home(): boolean {
        if (!this.send({ type: 'home', runId: this.state.runId })) return false;
        this.pool = Object.freeze([]); this.generator = null; this.nextPreview = null;
        this.replayResults = Object.freeze([]); this.queue = []; this.phaseStartTick = 0;
        return true;
    }
    press(source: string): boolean { return this.send({ type: 'charge', runId: this.state.runId, source }); }
    release(source: string): boolean {
        if (this.state.phase !== 'charging' || source !== this.state.inputOwner || !this.target) return false;
        const target = this.target;
        assertReachable(this.foot, target, this.config);
        return this.send({ type: 'launch', runId: this.state.runId, source, plan: {
            startFoot: this.foot, directionXZ: directionToTarget(this.foot, target),
            distance: chargeDistance(this.holdSeconds, this.config),
            flightTime: descendingLandingTime(this.foot.y, target.topY, this.config), targetId: target.id,
        } });
    }
    cancel(source?: string, reason?: string): boolean {
        return this.send({ type: 'cancel', runId: this.state.runId, source, reason });
    }
    pause(reason = 'pause'): boolean { return this.send({ type: 'pause', runId: this.state.runId, reason }); }
    resume(): boolean { return this.send({ type: 'resume', runId: this.state.runId }); }
    step(): boolean {
        if (!this.machine.advanceTick()) return false;
        const state = this.state, token = [REDACTED] runId: state.runId, jumpId: state.jumpId! };
        if (state.phase === 'airborne') {
            const plan = state.jumpPlan!;
            const elapsed = (state.tick - plan.startTick) * this.config.fixedStepSeconds;
            this.position = sampleJump(plan, elapsed, this.config);
            if (elapsed + Number.EPSILON >= plan.flightTime) this.touchDown();
        } else if (state.phase === 'landing' && state.tick - this.phaseStartTick >= 1) {
            if (state.landingOutcome === 'current') this.send({ type: 'finishLanding', ...token });
            else { this.send({ type: 'beginRecenter', ...token }); this.phaseStartTick = this.state.tick; }
        } else if (state.phase === 'recentering' && state.tick - this.phaseStartTick >= Math.ceil(this.config.cameraMoveSeconds / this.config.fixedStepSeconds)) {
            const currentId = state.targetId!, targetId = currentId + 1;
            if (this.send({ type: 'finishRecenter', ...token, currentId, targetId })) {
                this.pool = Object.freeze([...this.pool, this.nextPreview!].slice(-this.config.platformPoolLimit));
                this.nextPreview = null;
            }
        } else if (state.phase === 'falling') {
            const plan = state.jumpPlan!, end = sampleJump(plan, plan.flightTime, this.config);
            const elapsed = (state.tick - this.phaseStartTick) * this.config.fixedStepSeconds;
            const velocity = this.config.verticalVelocity - this.config.gravity * plan.flightTime;
            this.position = Object.freeze({ ...end, y: end.y + velocity * elapsed - this.config.gravity * elapsed * elapsed / 2 });
            if (state.tick - this.phaseStartTick >= Math.ceil(plan.flightTime / this.config.fixedStepSeconds)) this.send({ type: 'finishFall', ...token });
        }
        return true;
    }
    private touchDown(): void {
        const plan = this.state.jumpPlan!, current = this.current!, target = this.target!;
        const classification = classifyLanding(this.foot, current, target, this.config);
        const token = [REDACTED] runId: plan.runId, jumpId: plan.jumpId };
        if (classification === 'target-center' || classification === 'target-normal') {
            const upcoming = this.pool.find(p => p.id === target.id + 1)!;
            // Validate actual (possibly off-center) foot before score can change.
            assertReachable(this.foot, upcoming, this.config);
            this.nextPreview = this.generator!.next(upcoming).platform;
            this.position = Object.freeze({ ...this.foot, y: target.topY });
            this.send({ type: 'land', ...token, outcome: 'target' });
            this.send({ type: 'score', ...token, center: classification === 'target-center' });
        } else if (classification === 'current') {
            this.position = Object.freeze({ ...this.foot, y: current.topY });
            this.send({ type: 'land', ...token, outcome: 'current' });
        } else this.send({ type: 'fall', ...token, reason: 'miss' });
        this.phaseStartTick = this.state.tick;
        this.replayResults = Object.freeze([...this.replayResults, Object.freeze({ tick: this.state.tick,
            jumpId: plan.jumpId, classification, foot: this.foot, score: this.state.score, streak: this.state.streak })]);
    }
    private send(command: RunCommand): boolean {
        const result = this.machine.dispatch(command);
        if (result.accepted) this.queue.push(...result.events);
        return result.accepted;
    }
}

import { createGameConfig, DEFAULT_GAME_CONFIG, normalizeSeed } from './config';
import { ActivePhase, CallbackToken, DomainEvent, GameConfig, JumpPlan, JumpPlanDraft, JumpToken, LandingOutcome, RunState } from './types';

export type JumpEventKind = 'Scored' | 'Failed';
/** Publication boundary only; deliberately contains no collision or reward rules. */
export class JumpEventBoundary {
    private runId = 0;
    private lastJumpId = 0;
    private activeJumpId: number | null = null;
    private claimed = new Set<JumpEventKind>();
    startRun(runId: number): boolean {
        if (!Number.isSafeInteger(runId) || runId <= this.runId) return false;
        this.runId = runId; this.lastJumpId = 0; this.activeJumpId = null; this.claimed.clear();
        return true;
    }
    openJump(token: [REDACTED] boolean {
        if (token.runId !== this.runId || !Number.isSafeInteger(token.jumpId) || token.jumpId <= this.lastJumpId) return false;
        this.lastJumpId = token.jumpId; this.activeJumpId = token.jumpId; this.claimed.clear();
        return true;
    }
    closeJump(token: [REDACTED] boolean {
        if (token.runId !== this.runId || token.jumpId !== this.activeJumpId) return false;
        this.activeJumpId = null; this.claimed.clear(); return true;
    }
    claim(token: [REDACTED], kind: JumpEventKind): boolean {
        if ((kind !== 'Scored' && kind !== 'Failed') || token.runId !== this.runId ||
            token.jumpId !== this.activeJumpId || this.claimed.has(kind)) return false;
        this.claimed.add(kind);
        return true;
    }
}

export type RunCommand =
    { readonly type: 'start'; readonly seed?: number; } |
    { readonly type: 'home'; readonly runId: number; } |
    { readonly type: 'charge'; readonly runId: number; readonly source: string; } |
    { readonly type: 'cancel'; readonly runId: number; readonly source?: string; readonly reason?: string; } |
    { readonly type: 'launch'; readonly runId: number; readonly source: string; readonly plan: JumpPlanDraft; } |
    { readonly type: 'pause'; readonly runId: number; readonly reason?: string; } |
    { readonly type: 'resume'; readonly runId: number; } |
    ({ readonly type: 'land'; readonly outcome: LandingOutcome; } & JumpToken) |
    ({ readonly type: 'score'; readonly center: boolean; } & JumpToken) |
    ({ readonly type: 'beginRecenter'; } & JumpToken) |
    ({ readonly type: 'finishRecenter'; readonly currentId: number; readonly targetId: number; } & JumpToken) |
    ({ readonly type: 'finishLanding'; } & JumpToken) |
    ({ readonly type: 'fall'; readonly reason?: string; } & JumpToken) |
    ({ readonly type: 'finishFall'; } & JumpToken);
export interface CommandResult {
    readonly accepted: boolean;
    readonly reason: string | null;
    readonly state: Readonly<RunState>;
    readonly events: readonly DomainEvent[];
}

export class RunStateMachine {
    private readonly config: Readonly<GameConfig>;
    private value: Readonly<RunState>;
    private nextJumpId = 0;
    private fallReason = 'miss';
    private readonly boundary = new JumpEventBoundary();
    constructor(config: GameConfig = DEFAULT_GAME_CONFIG) {
        this.config = createGameConfig(config);
        this.value = this.emptyState(0, 'menu', this.config.seed);
    }
    get state(): Readonly<RunState> { return this.value; }
    isCurrent(token: [REDACTED] boolean {
        return token.runId === this.value.runId && this.value.phase !== 'menu' &&
            (token.jumpId === undefined || token.jumpId === this.value.jumpId);
    }
    guardCallback(token: [REDACTED], callback: () => void): boolean {
        if (!this.isCurrent(token) || this.value.phase === 'paused' || this.value.phase === 'gameover') return false;
        callback(); return true;
    }
    advanceTick(): boolean {
        if (['menu', 'paused', 'gameover'].indexOf(this.value.phase) !== -1) return false;
        if (!Number.isSafeInteger(this.value.tick + 1)) throw new RangeError('tick overflow');
        this.patch({ tick: this.value.tick + 1 }); return true;
    }
    /** Phase02 must atomically combine this reservation with its score reducer/event. */
    claimJumpEvent(token: [REDACTED], kind: 'Scored'): boolean {
        if (!this.isCurrent(token) || this.value.phase !== 'landing' || this.value.landingOutcome !== 'target') return false;
        return this.boundary.claim(token, kind);
    }
    dispatch(command: RunCommand): CommandResult {
        const events: DomainEvent[] = [];
        const reject = (reason: string) => this.result(false, reason, events);
        const emit = (event: DomainEvent) => events.push(Object.freeze(event));
        const base = () => ({ runId: this.value.runId, tick: this.value.tick });
        if (command.type === 'start') {
            let seed: number;
            try { seed = normalizeSeed(command.seed === undefined ? this.config.seed : command.seed); }
            catch (_) { return reject('invalid-seed'); }
            const runId = this.value.runId + 1;
            if (!Number.isSafeInteger(runId)) return reject('run-id-overflow');
            this.value = this.emptyState(runId, 'ready', seed);
            this.nextJumpId = 0; this.fallReason = 'miss'; this.boundary.startRun(runId);
            emit({ ...base(), type: 'Started', seed });
            return this.result(true, null, events);
        }
        if (!this.isCurrent(command)) return reject('stale-token');
        if (['land', 'score', 'beginRecenter', 'finishRecenter', 'finishLanding', 'fall', 'finishFall'].indexOf(command.type) !== -1) {
            const jumpId = (command as JumpToken).jumpId;
            if (!Number.isSafeInteger(jumpId) || jumpId <= 0 || jumpId !== this.value.jumpId) return reject('stale-jump');
        }
        switch (command.type) {
            case 'home': {
                const runId = this.value.runId + 1;
                if (!Number.isSafeInteger(runId)) return reject('run-id-overflow');
                emit({ ...base(), type: 'Returned' });
                this.value = this.emptyState(runId, 'menu', this.value.seed);
                this.boundary.startRun(runId); this.nextJumpId = 0;
                break;
            }
            case 'charge':
                if (this.value.phase !== 'ready') return reject('illegal-phase');
                if (typeof command.source !== 'string' || !command.source.trim()) return reject('invalid-source');
                this.patch({ phase: 'charging', inputOwner: command.source, chargeStartTick: this.value.tick });
                emit({ ...base(), type: 'Charge', action: 'begin', source: command.source });
                break;
            case 'cancel':
                if (this.value.phase !== 'charging') return reject('illegal-phase');
                if (command.source !== undefined && command.source !== this.value.inputOwner) return reject('not-owner');
                this.cancelCharge(events, command.reason || 'cancel');
                break;
            case 'launch': {
                if (this.value.phase !== 'charging') return reject('illegal-phase');
                if (command.source !== this.value.inputOwner) return reject('not-owner');
                const seconds = (this.value.tick - this.value.chargeStartTick!) * this.config.fixedStepSeconds;
                if (seconds + Number.EPSILON < this.config.minChargeSeconds) {
                    this.cancelCharge(events, 'short-charge'); break;
                }
                if (!this.validPlan(command.plan)) return reject('invalid-plan');
                const jumpId = this.nextJumpId + 1;
                if (!Number.isSafeInteger(jumpId)) return reject('jump-id-overflow');
                const plan: JumpPlan = Object.freeze({ ...command.plan, runId: this.value.runId, jumpId,
                    startTick: this.value.tick, startFoot: Object.freeze({ ...command.plan.startFoot }),
                    directionXZ: Object.freeze({ ...command.plan.directionXZ }) });
                this.nextJumpId = jumpId; this.boundary.openJump(plan);
                this.patch({ phase: 'airborne', jumpId, jumpPlan: plan, inputOwner: null, chargeStartTick: null });
                emit({ ...base(), type: 'Jump', jumpId, plan });
                break;
            }
            case 'pause': {
                const phase = this.value.phase;
                if (phase === 'paused' || phase === 'gameover') return reject('illegal-phase');
                if (phase === 'charging') this.cancelCharge(events, command.reason || 'pause');
                const resumePhase = this.value.phase as Exclude<ActivePhase, 'charging'>;
                this.patch({ phase: 'paused', resumePhase });
                emit({ ...base(), type: 'Paused', resumePhase, reason: command.reason || 'pause' });
                break;
            }
            case 'resume': {
                if (this.value.phase !== 'paused' || !this.value.resumePhase) return reject('illegal-phase');
                const phase = this.value.resumePhase;
                this.patch({ phase, resumePhase: null });
                emit({ ...base(), type: 'Resumed', phase });
                break;
            }
            case 'land':
                if (this.value.phase !== 'airborne') return reject('illegal-phase');
                if (command.outcome !== 'target' && command.outcome !== 'current') return reject('invalid-outcome');
                this.patch({ phase: 'landing', landingOutcome: command.outcome });
                emit({ ...base(), type: 'Landed', jumpId: command.jumpId, outcome: command.outcome });
                break;
            case 'score': {
                if (this.value.phase !== 'landing' || this.value.landingOutcome !== 'target') return reject('illegal-phase');
                if (typeof command.center !== 'boolean') return reject('invalid-score');
                const streak = command.center ? this.value.streak + 1 : 0;
                const delta = command.center ? this.config.centerScoreMultiplier * Math.min(streak, this.config.maxRewardStreak) : this.config.normalScore;
                const score = this.value.score + delta;
                if (!Number.isSafeInteger(score) || !Number.isSafeInteger(streak)) return reject('score-overflow');
                if (!this.boundary.claim(command, 'Scored')) return reject('duplicate-event');
                this.patch({ score, streak });
                emit({ ...base(), type: 'Scored', jumpId: command.jumpId, delta, score, streak });
                break;
            }
            case 'beginRecenter':
                if (this.value.phase !== 'landing' || this.value.landingOutcome !== 'target') return reject('illegal-phase');
                this.patch({ phase: 'recentering' });
                break;
            case 'finishRecenter':
                if (this.value.phase !== 'recentering') return reject('illegal-phase');
                if (command.currentId !== this.value.targetId || !Number.isSafeInteger(command.targetId) || command.targetId <= command.currentId) return reject('invalid-platform-ids');
                this.finishJump({ currentId: command.currentId, targetId: command.targetId });
                break;
            case 'finishLanding':
                if (this.value.phase !== 'landing' || this.value.landingOutcome !== 'current') return reject('illegal-phase');
                this.finishJump({});
                break;
            case 'fall':
                if (this.value.phase !== 'airborne') return reject('illegal-phase');
                this.fallReason = command.reason || 'miss'; this.patch({ phase: 'falling' });
                break;
            case 'finishFall':
                if (this.value.phase !== 'falling') return reject('illegal-phase');
                if (!this.boundary.claim(command, 'Failed')) return reject('duplicate-event');
                this.patch({ phase: 'gameover' });
                emit({ ...base(), type: 'Failed', jumpId: command.jumpId, reason: this.fallReason });
                break;
            default: return reject('unknown-command');
        }
        return this.result(true, null, events);
    }
    private cancelCharge(events: DomainEvent[], reason: string): void {
        events.push(Object.freeze({ type: 'Charge', action: 'cancel', source: this.value.inputOwner!,
            runId: this.value.runId, tick: this.value.tick, reason }));
        this.patch({ phase: 'ready', inputOwner: null, chargeStartTick: null });
    }
    private validPlan(plan: JumpPlanDraft): boolean {
        if (!plan || !plan.startFoot || !plan.directionXZ) return false;
        const values = [plan.startFoot.x, plan.startFoot.y, plan.startFoot.z,
            plan.directionXZ.x, plan.directionXZ.z, plan.distance, plan.flightTime];
        return values.every(Number.isFinite) && plan.targetId === this.value.targetId &&
            Math.abs(Math.hypot(plan.directionXZ.x, plan.directionXZ.z) - 1) <= this.config.geometryEpsilon &&
            plan.distance >= this.config.minJumpDistance && plan.distance <= this.config.maxJumpDistance &&
            Math.abs(plan.flightTime - 2 * this.config.verticalVelocity / this.config.gravity) <= this.config.geometryEpsilon;
    }
    private finishJump(platforms: Partial<RunState>): void {
        this.boundary.closeJump({ runId: this.value.runId, jumpId: this.value.jumpId! });
        this.patch({ ...platforms, phase: 'ready', jumpId: null, jumpPlan: null, landingOutcome: null });
    }
    private patch(values: Partial<RunState>): void { this.value = Object.freeze({ ...this.value, ...values }); }
    private emptyState(runId: number, phase: 'menu' | 'ready', seed: number): Readonly<RunState> {
        return Object.freeze({ runId, phase, seed, tick: 0, score: 0, streak: 0,
            currentId: phase === 'menu' ? null : 0, targetId: phase === 'menu' ? null : 1,
            jumpId: null, chargeStartTick: null, inputOwner: null, jumpPlan: null,
            resumePhase: null, landingOutcome: null });
    }
    private result(accepted: boolean, reason: string | null, events: DomainEvent[]): CommandResult {
        return Object.freeze({ accepted, reason, state: this.value, events: Object.freeze(events) });
    }
}

import { Node, Vec3 } from 'cc';
import { PlatformSpec } from '../core/types';

/** Presentation only. Camera moves on successful landing, using simulation ticks (pause-safe). */
export class CameraFollow {
    private from = new Vec3();
    private to = new Vec3();
    private startTick = 0;
    private moving = false;
    private readonly offset = new Vec3();
    constructor(private readonly camera: Node, private readonly durationTicks: number, initialCurrent: PlatformSpec, initialTarget: PlatformSpec) {
        const midpoint = this.midpoint(initialCurrent, initialTarget);
        Vec3.subtract(this.offset, camera.position, midpoint);
    }
    reset(current: PlatformSpec, target: PlatformSpec): void {
        this.moving = false; Vec3.add(this.to, this.midpoint(current, target), this.offset); this.camera.setPosition(this.to);
    }
    begin(tick: number, current: PlatformSpec, target: PlatformSpec): void {
        this.from.set(this.camera.position); Vec3.add(this.to, this.midpoint(current, target), this.offset);
        this.startTick = tick; this.moving = true;
    }
    render(tick: number, alpha: number): void {
        if (!this.moving) return;
        const q = Math.min(1, Math.max(0, (tick - this.startTick + alpha) / this.durationTicks));
        const smooth = q * q * (3 - 2 * q);
        this.camera.setPosition(Vec3.lerp(new Vec3(), this.from, this.to, smooth));
        if (q === 1) this.moving = false;
    }
    private midpoint(current: PlatformSpec, target: PlatformSpec): Vec3 {
        return new Vec3((current.centerXZ.x + target.centerXZ.x) / 2, 0, (current.centerXZ.z + target.centerXZ.z) / 2);
    }
}

